/**
 * Types for the module generated by `@ntatoud/content/vite`.
 *
 * The shapes are the readers' own return types, so this declaration cannot
 * drift from the schemas: it names them rather than restating them.
 */
declare module 'virtual:content' {
  import type {
    BlogPost,
    BlogPostDetail,
    Experience,
    Project,
    ProjectDetail,
    StageItem,
    TalkDetail,
  } from '@ntatoud/content'

  /** Published documents, ordered as the corresponding reader orders them. */
  export const blogPosts: ReadonlyArray<BlogPost>
  export const projects: ReadonlyArray<Project>
  export const experiences: ReadonlyArray<Experience>
  export const talks: ReadonlyArray<StageItem>

  /**
   * One lazily-imported chunk per document, keyed by slug — drafts included, so
   * an unpublished document keeps a reachable page even though no listing links
   * to it. A slug that does not exist is simply absent, which is what a route
   * turns into a 404.
   */
  export const loadBlogPost: Readonly<
    Record<string, (() => Promise<{ default: BlogPostDetail }>) | undefined>
  >
  export const loadProject: Readonly<
    Record<string, (() => Promise<{ default: ProjectDetail }>) | undefined>
  >
  export const loadTalk: Readonly<
    Record<string, (() => Promise<{ default: TalkDetail }>) | undefined>
  >
}
